"use client";
import { ArtemisScope } from "./artemis-scope";
import View0 from "./components/content-sections/variants/01-platform-overview";
import View1 from "./components/content-sections/variants/02-metrics-gallery";
import View2 from "./components/content-sections/variants/03-capability-showcase";
import View3 from "./components/content-sections/variants/04-value-grid";
import View4 from "./components/content-sections/variants/05-engagement-sequence";
const variants = {"platform-overview":View0,"metrics-gallery":View1,"capability-showcase":View2,"value-grid":View3,"engagement-sequence":View4};
export interface ArtemisContentSectionsProps { className?: string; variant?: "platform-overview" | "metrics-gallery" | "capability-showcase" | "value-grid" | "engagement-sequence"; }
export function ArtemisContentSections({ className, variant = "platform-overview" }: ArtemisContentSectionsProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View/></div></ArtemisScope>;}
